import unittest
from src.ledger.categories import normalize_category
from src.ledger.store import make_expense

class CategoryTests(unittest.TestCase):
    def test_normalize_category(self):
        self.assertEqual(normalize_category('  Home   Office '), 'home office')
        self.assertEqual(normalize_category('   '), 'uncategorized')

    def test_store_uses_normalized_category(self):
        self.assertEqual(make_expense(12, '  Home   Office ')['category'], 'home office')

